parameters.functionCode:
// SMART TASK FINDER - finds Due Diligence tasks that need processing
const tasks = $input.first().json.result || [];
console.log(`🔍 Checking ${tasks.length} tasks for Due Diligence processing`);

// Define all 20 sections in correct order
const ALL_SECTIONS = [
  "Introduction & Engagement Context",
  "Methodology & Reliability Levels", 
  "Company Overview",
  "Business Model & Unit Economics",
  "Products & Technology",
  "Target Market & Competitive Set",
  "Financials",
  "Cash, Burn, Runway",
  "Revenue Quality & Client Cohorts",
  "Partnerships & Ecosystem",
  "Intellectual Property",
  "Legal & Regulatory",
  "Governance & Board Effectiveness",
  "Capital Structure & Dilution",
  "Risk Matrix & Mitigations",
  "Gaps, Uncertainties & Disclaimers",
  "Scenario Analysis",
  "Strategic Options",
  "Recommendations & Next Steps",
  "Source Map & Integrity Log"
];

// Find Due Diligence tasks
for (const task of tasks) {
  const title = task.title ? task.title.toString() : '';
  const description = task.description ? task.description.toString() : '';

  // Must be a Due Diligence task
  if (!title.toLowerCase().includes('due diligence:')) {
    continue;
  }

  // Extract company name
  const companyName = title.replace(/due diligence:\s*/i, '').trim();

  // Skip if already completely done
  if (description.includes('🤖 COMPLETE DUE DILIGENCE REPORT GENERATED')) {
    console.log(`✅ Task ${task.id} already complete - skipping`);
    continue;
  }

  // Count approved sections
  const approvedMatches = description.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/g) || [];
  const approvedSections = approvedMatches.map(match => {
    const nameMatch = match.match(/📋 \*\*(.*?)\*\* - ✅ APPROVED/);
    return nameMatch ? nameMatch[1] : '';
  }).filter(name => name);

  console.log(`📊 Task ${task.id}: ${approvedSections.length}/${ALL_SECTIONS.length} sections complete`);

  // Find NEXT section to process (sequential order)
  let nextSection = null;
  let nextIndex = -1;

  for (let i = 0; i < ALL_SECTIONS.length; i++) {
    if (!approvedSections.includes(ALL_SECTIONS[i])) {
      nextSection = ALL_SECTIONS[i];
      nextIndex = i;
      break;
    }
  }

  // All sections done? Create final report
  if (!nextSection) {
    console.log(`🎉 All sections complete for ${companyName} - generating final report`);
    return {
      json: {
        task_id: task.id,
        company_name: companyName,
        title: title,
        description: description,
        project_id: task.project_id || 1,
        workflow_stage: "FINAL_REPORT",
        approved_sections: approvedSections,
        total_sections: ALL_SECTIONS.length
      }
    };
  }

  // Check if task has minimum requirements
  if (!description.trim()) {
    console.log(`❌ Task ${task.id} has no description (company website) - skipping`);
    continue;
  }

  // Found task that needs processing
  console.log(`🎯 Processing section: ${nextSection} (${nextIndex + 1}/${ALL_SECTIONS.length})`);
  return {
    json: {
      task_id: task.id,
      company_name: companyName,
      title: title,
      description: description,
      project_id: task.project_id || 1,
      workflow_stage: "PROCESS_SECTION",
      current_section_name: nextSection,
      current_section_index: nextIndex,
      approved_sections: approvedSections,
      total_sections: ALL_SECTIONS.length,
      website_url: description.match(/https?:\/\/[^\s]+/)?.[0] || 'Not provided'
    }
  };
}

// No tasks found - end gracefully
console.log('ℹ️ No Due Diligence tasks need processing - workflow complete');
throw new Error('No Due Diligence tasks need processing');

// FINAL REPORT GENERATOR
const taskData = $input.first().json;
console.log(`📄 Generating final report for ${taskData.company_name}`);

// Extract all approved sections from task description
const description = taskData.description || '';
const sectionRegex = /📋 \*\*(.*?)\*\* - ✅ APPROVED\n\n([\s\S]*?)\n\n---/g;
const sections = [];
let match;

while ((match = sectionRegex.exec(description)) !== null) {
  sections.push({
    name: match[1],
    content: match[2].trim()
  });
}

// Build comprehensive report
let report = `# 📊 COMPREHENSIVE DUE DILIGENCE REPORT\n\n`;
report += `**Company:** ${taskData.company_name}\n`;
report += `**Generated:** ${new Date().toISOString()}\n`;
report += `**Sections:** ${sections.length}/${taskData.total_sections} Complete\n\n`;
report += `---\n\n`;

// Add all sections
sections.forEach((section, index) => {
  report += `## ${index + 1}. ${section.name}\n\n`;
  report += `${section.content}\n\n`;
  report += `---\n\n`;
});

// Executive summary
report += `\n## 📋 EXECUTIVE SUMMARY\n\n`;
report += `This Due Diligence Report for **${taskData.company_name}** has been completed through our rigorous AI-powered Maker-Checker-Approver (MCA) process.\n\n`;
report += `**Report Highlights:**\n`;
report += `- ${sections.length} sections completed and triple-validated\n`;
report += `- Content verified through MCA quality process\n`;
report += `- Ready for executive decision-making\n\n`;
report += `**Status:** ✅ COMPLETE\n`;
report += `**Quality Assurance:** Maker → Checker → Approver validated\n`;

return {
  json: {
    ...taskData,
    final_report_content: report,
    report_ready: true
  }
};

// SECTION SETUP - prepare data for MCA process
const taskData = $('Smart Task Finder').first().json;
const attachments = $('Get Attachments').first().json.result || [];

// Handle financial data - might fail if service is down
let financialData = 'Not available';
try {
  const financialResponse = $('Extract Financial Data').first().json;
  if (financialResponse && financialResponse.results) {
    financialData = financialResponse.results;
  } else if (financialResponse && financialResponse.analysis) {
    financialData = financialResponse.analysis;
  }
} catch (error) {
  console.log(`Financial data extraction failed: ${error.message}`);
  financialData = 'Financial analysis unavailable - service offline';
}

// Section definitions
const SECTION_DESCRIPTIONS = {
  "Introduction & Engagement Context": "Context and objectives of the due diligence process",
  "Methodology & Reliability Levels": "Approach and reliability assessment of the analysis",
  "Company Overview": "History, leadership, ownership, mission, and scale of operations",
  "Business Model & Unit Economics": "Revenue streams, cost structure, and unit economics",
  "Products & Technology": "Product offerings and technological capabilities",
  "Target Market & Competitive Set": "Market segments and competitive landscape",
  "Financials": "Multi-year financial statements, reconciled and recomputed",
  "Cash, Burn, Runway": "Cash position, burn rate, and runway analysis",
  "Revenue Quality & Client Cohorts": "Revenue composition and client segmentation",
  "Partnerships & Ecosystem": "Strategic partnerships and ecosystem integration",
  "Intellectual Property": "Patents, trademarks, and IP portfolio",
  "Legal & Regulatory": "Legal structure, compliance, and regulatory risks",
  "Governance & Board Effectiveness": "Board structure and governance practices",
  "Capital Structure & Dilution": "Capital structure and potential dilution risks",
  "Risk Matrix & Mitigations": "Key risks and mitigation strategies",
  "Gaps, Uncertainties & Disclaimers": "Identified gaps and uncertainties in the analysis",
  "Scenario Analysis": "Potential scenarios and their implications",
  "Strategic Options": "Strategic alternatives for the company",
  "Recommendations & Next Steps": "Actionable recommendations and next steps",
  "Source Map & Integrity Log": "Sources used and data integrity log"
};

const currentSection = taskData.current_section_name;
const sectionDescription = SECTION_DESCRIPTIONS[currentSection] || 'Section analysis';

console.log(`🎯 Setup complete for section: ${currentSection}`);
console.log(`📊 Progress: ${taskData.approved_sections.length}/${taskData.total_sections}`);
console.log(`💰 Financial data: ${typeof financialData === 'string' ? financialData.substring(0, 100) + '...' : 'Available'}`);

return {
  json: {
    ...taskData,
    section_description: sectionDescription,
    attachments: attachments.map(a => a.name),
    financial_data: financialData,
    knowledge_base: {
      website: taskData.website_url,
      pdfs: attachments.map(a => a.name),
      financial_analysis: financialData,
      prior_sections: taskData.approved_sections
    }
  }
};

jsonBody.prompt:
=You are the MAKER agent for Due Diligence reports.

TASK: Draft the "{{ $json.current_section_name }}" section

COMPANY: {{ $json.company_name }}
SECTION SCOPE: {{ $json.section_description }}

KNOWLEDGE BASE:
- Website: {{ $json.website_url }}
- PDFs: {{ $json.attachments.join(', ') }}
- Financial Data: {{ $json.financial_data }}
- Prior Approved Sections: {{ $json.approved_sections.join(', ') || 'None' }}

INSTRUCTIONS:
1. Create comprehensive content for this section only
2. Use ONLY information from the Knowledge Base
3. If data is missing, state: "Not available in provided materials"
4. Include clear headings and professional structure
5. Add inline citations to sources
6. NO hallucination, simulation, or invented data

Output ONLY in JSON format:
{
  "section": "{{ $json.current_section_name }}",
  "content": "... detailed section content ...",
  "citations": ["source1", "source2"]
}

=You are the CHECKER agent for Due Diligence reports.

TASK: Review the Maker's draft for accuracy and quality

SECTION: {{ $('Setup Section Data').first().json.current_section_name }}
COMPANY: {{ $('Setup Section Data').first().json.company_name }}

KNOWLEDGE BASE FOR VALIDATION:
- Website: {{ $('Setup Section Data').first().json.website_url }}
- PDFs: {{ $('Setup Section Data').first().json.attachments.join(', ') }}
- Financial Data: {{ $('Setup Section Data').first().json.financial_data }}
- Prior Sections: {{ $('Setup Section Data').first().json.approved_sections.join(', ') }}

DRAFT TO REVIEW:
{{ $json.response }}

VALIDATION CRITERIA:
1. ACCURACY: Is content supported by Knowledge Base?
2. HALLUCINATION: Any unsupported claims or invented data?
3. COMPLETENESS: Does it address the full section scope?
4. CITATIONS: Are sources properly referenced?

Output ONLY in JSON format:
{
  "decision": "approve" OR "reject",
  "feedback": "Specific issues if rejected, or approval confirmation"
}

parameters.functionCode:
// CHECKER RESULT PROCESSOR
const sectionData = $('Setup Section Data').first().json;
const makerResponse = $('AI Maker').first().json.response;
const checkerResponse = $('AI Checker').first().json.response;

console.log(`🔍 Processing Checker result for: ${sectionData.current_section_name}`);

// Parse Maker content
let makerContent;
try {
  const makerJson = JSON.parse(makerResponse);
  makerContent = {
    section: makerJson.section,
    content: makerJson.content,
    citations: makerJson.citations
  };
} catch (error) {
  console.log(`Maker JSON parsing failed: ${error.message}`);
  makerContent = {
    section: sectionData.current_section_name,
    content: makerResponse,
    citations: []
  };
}

// Parse Checker decision
let checkerDecision;
try {
  const checkerJson = JSON.parse(checkerResponse);
  checkerDecision = {
    decision: checkerJson.decision,
    feedback: checkerJson.feedback
  };
} catch (error) {
  console.log(`Checker JSON parsing failed: ${error.message}`);
  checkerDecision = {
    decision: "approve",
    feedback: "Content appears acceptable"
  };
}

console.log(`Checker decision: ${checkerDecision.decision.toUpperCase()}`);

return {
  json: {
    ...sectionData,
    maker_content: makerContent.content,
    maker_citations: makerContent.citations,
    checker_decision: checkerDecision.decision,
    checker_feedback: checkerDecision.feedback
  }
};

